126	// ---------------------------------------------------------------------------
127	
128	function sendJson(
129	  res: ServerResponse,
130	  status: number,
131	  data: unknown,
132	  port: number
133	): void {
134	  const body = JSON.stringify(data);
135	  res.writeHead(status, {
136	    'Content-Type': 'application/json',
137	    'Content-Length': Buffer.byteLength(body),
138	    ...corsHeaders(port),
139	    ...securityHeaders(),
140	  });
141	  res.end(body);
142	}
143	
144	function sendError(
145	  res: ServerResponse,
146	  status: number,
147	  code: string,
148	  message: string,
149	  port: number
150	): void {
151	  sendJson(res, status, { error: { code, message } }, port);
152	}
153	
154	export function apiErrorToStatus(code: string): number {
155	  switch (code) {
156	    case 'NOT_FOUND':
157	      return 404;
158	    case 'FORBIDDEN':
159	      return 403;
160	    case 'VALIDATION_ERROR':
161	      return 400;
162	    case 'CONFLICT':
163	      return 409;
164	    default:
165	      return 500;
166	  }
167	}
